from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
old="""    Promise.all([\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__actDate',      data:_blobOnly(S.actDate),      updated_at:_mnow},{onConflict:'trip_id,detail_key'}),\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__actMoment',    data:_blobOnly(S.actMoment),    updated_at:_mnow},{onConflict:'trip_id,detail_key'}),\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__actTimeStart', data:_blobOnly(S.actTimeStart), updated_at:_mnow},{onConflict:'trip_id,detail_key'}),\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__actTimeEnd',   data:_blobOnly(S.actTimeEnd),   updated_at:_mnow},{onConflict:'trip_id,detail_key'}),\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__actTime',      data:_blobOnly(S.actTime),      updated_at:_mnow},{onConflict:'trip_id,detail_key'}),\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__actDay',       data:_blobOnly(S.actDay),       updated_at:_mnow},{onConflict:'trip_id,detail_key'}),\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__done',         data:_blobOnly(S.done),         updated_at:_mnow},{onConflict:'trip_id,detail_key'})\n    ]).catch(function(e){ console.error('[PlaniTrip] migration blobs upsert:', e); });\n"""
new="""    // P0.8-B : ne jamais réécrire les blobs de planning depuis le cache pendant une\n    // migration legacy→stable. Les clés _sid_ en sont filtrées et ces writes ne servent donc\n    // pas la migration ; ils peuvent en revanche écraser une valeur Supabase plus récente\n    // (date/moment/horaires) avant que loadActivityDetails() ne la recharge.\n    Promise.all([\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__actDay',       data:_blobOnly(S.actDay),       updated_at:_mnow},{onConflict:'trip_id,detail_key'}),\n      sb.from('activity_details').upsert({trip_id:_mtid,detail_key:'__planitrip__done',         data:_blobOnly(S.done),         updated_at:_mnow},{onConflict:'trip_id,detail_key'})\n    ]).catch(function(e){ console.error('[PlaniTrip] migration blobs upsert:', e); });\n"""
if s.count(old)!=1: raise SystemExit(f'W6 planning block match={s.count(old)}')
s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')
